sp_header_footer.client_script:
api.controller = function ($rootScope, $scope, $injector, spUtil, $location,
                           $uibModal, cabrillo, $timeout, $window, i18n) {

  $scope.logoText = i18n.format(
    i18n.getMessage('Go to {0} Homepage'), $scope.portal.title
  );

  $scope.collapse = function() {
    $rootScope.$emit('sp-navbar-collapse');
  };

  $scope.avatarProfile = {
    userID:   $scope.user,
    name:     $scope.user.name,
    initials: $window.NOW && $window.NOW.user_initials
              ? $window.NOW.user_initials : ''
  };

  if ($window.NOW && $window.NOW.user_avatar)
    $scope.avatarProfile.userImage = $window.NOW.user_avatar;

  // Native app check
  try {
    if (cabrillo.isNative()) {
      $scope.isViewNative       = $window.innerWidth < 767;
      $scope.isViewNativeTablet = $window.innerWidth >= 767;
    }
  } catch(e) {}

  // ── Build logoutUrl ONCE on init and bind to scope ──
  // Using ng-href instead of ng-click avoids ALL navbar flicker issues
  (function buildLogoutUrl() {
    var url = null;

    // 1. Try portal.logoutUrl from current scope
    try { url = $scope.portal && $scope.portal.logoutUrl; } catch(e) {}

    // 2. Walk parent scopes
    if (!url || url === '/logout.do' || url.trim() === '') {
      try {
        var s = $scope.$parent;
        while (s) {
          if (s.portal && s.portal.logoutUrl &&
              s.portal.logoutUrl !== '/logout.do') {
            url = s.portal.logoutUrl;
            break;
          }
          s = s.$parent;
        }
      } catch(e) {}
    }

    // 3. Hardcoded fallback using sysparm_logout=true (native SP logout)
    if (!url || url === '/logout.do' || url.trim() === '') {
      url = '/applicant?id=login&sysparm_logout=true';
    }

    $scope.logoutUrl = url;
  })();

  $scope.openPopUp = function() {
    var url = "$chat_support.do?queueID=" + $scope.data.connect_support_queue_id;
    $location.url(url, "popup", "width=900, height=600");
  };

  $scope.openLogin = function() {
    $scope.modalInstance = $uibModal.open({
      templateUrl: 'modalLogin',
      scope: $scope
    });
    var pageRoot = angular.element('.sp-page-root');
    $scope.modalInstance.rendered.then(function() {
      try {
        var $uibModalStack = $injector.get('$uibModalStack');
        var modalObj       = $uibModalStack.getTop();
        var modal          = modalObj.value.modalDomEl;
        modal.attr('aria-label', modal.find('.panel-title').html());
        modal.attr('aria-modal', 'true');
        pageRoot.attr('aria-hidden', 'true');
      } catch(e) {}
    });
    $scope.modalInstance.closed.then(function() {
      pageRoot.attr('aria-hidden', 'false');
    });
  };

  // ── Responsive avatar logic ──
  var nav = document.getElementById('responsiveNav');

  function isMDScreenSize() {
    return nav ? nav.classList.contains('responsive-tablet') : false;
  }

  function updateResponsiveClasses(width) {
    if (!nav) return;
    if (width <= 992) {
      nav.classList.add('responsive-tablet');
      nav.classList.remove('responsive-desktop');
    } else {
      nav.classList.add('responsive-desktop');
      nav.classList.remove('responsive-tablet');
    }
    $scope.showSMAvatar = isMDScreenSize();
    $scope.showAvatar   = !isMDScreenSize();
  }

  $scope.showSMAvatar = isMDScreenSize();
  $scope.showAvatar   = !isMDScreenSize();

  try {
    $scope.isAgentChatConfigured =
      (typeof g_has_agent_chat_config !== 'undefined')
        ? g_has_agent_chat_config : false;
  } catch(e) {
    $scope.isAgentChatConfigured = false;
  }

  if (nav) {
    try {
      new ResizeObserver(function(entries) {
        if (entries && entries[0])
          updateResponsiveClasses(entries[0].contentRect.width);
      }).observe(nav);
    } catch(e) {}
  }

  $rootScope.$on('sp.avatar_changed', function(evt, obj) {
    $scope.userID      = "";
    $scope.newAvatarId = obj.newAvatarId;
    $timeout(function() {
      $scope.userID = $scope.user;
      $("#gn-profile-dropdown .sub-avatar").css("background-image",
        'url("' + $scope.newAvatarId + '.iix?t=small")');
    });
  });

  $scope.isHomepage = function() {
    if (!$scope.page || !$scope.page.id) return true;
    return $scope.page.id === $scope.portal.homepage_dv;
  };
};

sp_header_footer.css:
/* ═══════════════════════════════════════════════════════
   GateNow Header Widget Styles
═══════════════════════════════════════════════════════ */

/* ─── Navbar base ────────────────────────────────────── */
.gn-navbar {
  position: fixed !important;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1050;
  background: linear-gradient(114.089deg, rgb(84, 60, 168) 17.665%, rgb(88, 107, 199) 114.38%) !important;
  border: none !important;

  min-height: 61px !important;
  margin-bottom: 0 !important;
  border-radius: 0 !important;
}
.gn-portal-logo {
  height: 36px;
  width: auto;
  max-width: 180px;
  object-fit: contain;
  display: block;
  filter: brightness(0) invert(1);
}

/* ─── Inner container (max 1440px, centered) ─────────── */
.gn-navbar-inner {
  max-width: 1440px;
  width: 100%;
  margin: 0 auto;
  padding: 0 36px;
  height: 61px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: relative;
}

/* ─── Brand / Logo ───────────────────────────────────── */
.navbar-header.gn-navbar-brand-wrap {
  float: none !important;
  height: 61px;
  display: flex;
  align-items: center;
}

.gn-brand {
  display: flex !important;
  align-items: center;
  gap: 8px;
  padding: 0 !important;
  height: 61px !important;
  line-height: 61px;
  text-decoration: none !important;
}

.gn-brand:hover {
  background: transparent !important;
  opacity: 0.88;
}

/* Dot-grid icon */
.gn-logo-icon {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  display: block;
}

/* Wordmark */
.gn-brand-text {
  font-family: 'Plus Jakarta Sans', 'Inter', 'Segoe UI', sans-serif;
  font-size: 21px;
  font-weight: 500;
  color: #ffffff;
  letter-spacing: -0.5px;
  line-height: 1;
}

.gn-brand-gate { letter-spacing: -0.6px; }
.gn-brand-now  { letter-spacing: 0; }

/* ─── Right-side nav ─────────────────────────────────── */
.gn-navbar-right {
  display: flex !important;
  align-items: center;
  float: none !important;
  margin: 0 !important;
  height: 61px;
}

.gn-nav-actions {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  align-items: center;
}

/* ─── Login link (logged-out state) ──────────────────── */
.gn-login-link {
  display: flex !important;
  align-items: center;
  gap: 7px;
  padding: 0 4px !important;
  height: 61px;
  color: #ffffff !important;
  text-decoration: none !important;
  font-family: 'Inter', 'Segoe UI', sans-serif;
  font-size: 14px;
  font-weight: 400;
  transition: opacity 0.18s ease;
  background: transparent !important;
}

.gn-login-link:hover {
  opacity: 0.78;
  background: transparent !important;
  color: #ffffff !important;
}

.gn-login-icon {
  width: 21px;
  height: 21px;
  flex-shrink: 0;
  display: block;
}

.gn-login-text {
  color: #ffffff;
  font-size: 14px;
}

/* ─── Generic nav link ───────────────────────────────── */
.gn-nav-link {
  display: flex !important;
  align-items: center;
  height: 61px;
  padding: 0 14px !important;
  color: rgba(255, 255, 255, 0.82) !important;
  font-size: 14px;
  text-decoration: none !important;
  transition: color 0.18s ease;
}
.gn-nav-link:hover { color: #ffffff !important; }

/* ─── Avatar dropdown button ─────────────────────────── */
.gn-avatar-dropdown { position: relative; }

.gn-avatar-btn {
  display: flex !important;
  align-items: center;
  gap: 8px;
  height: 61px;
  padding: 0 8px !important;
  color: #ffffff !important;
  text-decoration: none !important;
  font-size: 14px;
  transition: opacity 0.18s ease;
  cursor: pointer;
  background: transparent !important;
}
.gn-avatar-btn:hover { opacity: 0.82; background: transparent !important; }

.gn-user-name {
  color: #ffffff;
  font-size: 14px;
  font-family: 'Inter', sans-serif;
}

.gn-chevron {
  width: 12px;
  height: 12px;
  flex-shrink: 0;
  margin-left: 2px;
  transition: transform 0.2s ease;
}
.gn-avatar-dropdown.open .gn-chevron { transform: rotate(180deg); }

/* ─── Dropdown menu ──────────────────────────────────── */
.gn-dropdown-menu {
  border: none !important;
  border-radius: 10px !important;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.14), 0 2px 8px rgba(0,0,0,0.08) !important;
  padding: 6px !important;
  min-width: 160px !important;
  background: #ffffff !important;
  top: calc(100% + 4px) !important;
  right: 0 !important;
  left: auto !important;
}

.gn-dropdown-item {
  display: flex !important;
  align-items: center;
  gap: 8px;
  padding: 9px 14px !important;
  border-radius: 7px !important;
  color: #1D1D2E !important;
  font-size: 13.5px !important;
  font-family: 'Inter', sans-serif;
  transition: background 0.15s ease !important;
  text-decoration: none !important;
}
.gn-dropdown-item:hover {
  background: #EEEDFB !important;
  color: #5443AD !important;
}
.gn-dropdown-item:hover svg path,
.gn-dropdown-item:hover svg circle { stroke: #5443AD !important; }

.gn-dropdown-logout:hover {
  background: #FEE2E2 !important;
  color: #EF4444 !important;
}
.gn-dropdown-logout:hover svg path { stroke: #EF4444 !important; }

/* ─── Bottom separator line ──────────────────────────── */
.gn-navbar-separator {
  position: absolute;
  bottom: 0;
  left: 36px;
  right: 36px;
  height: 1px;
  background: rgba(255, 255, 255, 0.23);
  pointer-events: none;
}

/* ─── Mobile hamburger ───────────────────────────────── */
.gn-hamburger {
  border: 1.5px solid rgba(255, 255, 255, 0.5) !important;
  border-radius: 6px !important;
  margin-top: 13px !important;
  margin-right: 0 !important;
  background: transparent !important;
  padding: 7px 10px !important;
  transition: background 0.18s ease;
}
.gn-hamburger:hover { background: rgba(255,255,255,0.1) !important; }
.gn-hamburger .icon-bar { background: #ffffff !important; }

/* ─── Responsive ─────────────────────────────────────── */
@media (max-width: 992px) {
  .gn-navbar-inner { padding: 0 20px; }
  .gn-navbar-separator { left: 20px; right: 20px; }
}

@media (max-width: 768px) {
  .gn-navbar-right {
    height: auto !important;
    flex-direction: column;
    align-items: flex-start;
    background: linear-gradient(114.089deg, rgb(84, 60, 168) 17.665%, rgb(88, 107, 199) 114.38%);
    padding: 12px 0;
  }
  .gn-login-link, .gn-nav-link, .gn-avatar-btn { height: 44px; padding: 0 20px !important; }
}

/* ─── Page body offset (header is fixed) ─────────────── */
.sp-page-root { padding-top: 61px; }

sp_header_footer.script:
(function() {

  data.connect_support_queue_id = $sp.getValue('sp_chat_queue');
  data.login_page = $sp.getValue('login_page');
  data.profileBtnMsg = gs.getMessage("User options");
  data.toggleMsg = gs.getMessage("Toggle navigation");

  // Safe menu loading
  try {
    var menu = $sp.getValue("sp_rectangle_menu");
    data.menu = $sp.getWidgetFromInstance(menu);
  } catch(e) {
    data.menu = null;
    jslog('GateNow Header - menu load error: ' + e.message, 'gatenow-header');
  }

  // Safe language selector loading
  try {
    var i18nActive = gs.isPluginActivated('com.glide.i18n');
    data.langSelector = i18nActive ? $sp.getWidget('sp-lang-selector') : "";
  } catch(e) {
    data.langSelector = "";
  }

  // Parse menu items
  if (data.menu && data.menu.data) {
    data.menu.data.replace = true;
    data.hasLogin = false;
    data.hasMenuItems = false;

    try {
      if (data.menu.data.menu && data.menu.data.menu.items) {
        data.hasMenuItems = data.menu.data.menu.items.length > 0;
        for (var i in data.menu.data.menu.items) {
          var item = data.menu.data.menu.items[i];
          if (item.type == 'page' && item.sp_page == data.login_page) {
            data.hasLogin = true;
          }
        }
      }
    } catch(e) {
      jslog('GateNow Header - menu parse error: ' + e.message, 'gatenow-header');
    }
  }

  // Safe login widget
  try {
    data.loginWidget = $sp.getWidgetFromInstance('login-modal');
  } catch(e) {
    data.loginWidget = null;
  }

})();
